const out = { world: game.world.id, lookup: !!game.pentaryn?.rules };
const sp = game.packs.get("dnd-players-handbook.spells");
const docs = await sp.getDocuments();
out.spellCount = docs.length;
const nec = docs.filter(d => d.system.school === "nec");
out.necro = nec.map(d => ({ name: d.name, lvl: d.system.level,
  wiz: [...(d.system.sourceClass ? [d.system.sourceClass] : [])],
  ident: d.system.identifier })).sort((a,b)=>a.lvl-b.lvl||a.name.localeCompare(b.name));
const cl = game.packs.get("dnd-players-handbook.classes");
const ci = await cl.getIndex({fields:["type","system.classIdentifier"]});
out.wizSubclasses = [...ci].filter(e => e.type==="subclass" && e.system?.classIdentifier==="wizard").map(e=>e.name);
// find wizard spell list membership
const wizList = dnd5e?.registry?.spellLists?.forType?.("class","wizard");
out.hasRegistry = !!wizList;
if (wizList) { const ids = wizList.identifiers ?? wizList.uuids; out.wizListSize = ids?.size; 
  const uu = wizList.uuids ? [...wizList.uuids] : [];
  out.necroOnWizard = nec.filter(d => uu.includes(d.uuid)).map(d=>`${d.system.level}: ${d.name}`); }
return out;

const out = { world: game.world.id };
const sp = game.packs.get("dnd-players-handbook.spells");
const docs = await sp.getDocuments();
out.spellCount = docs.length;
const nec = docs.filter(d => d.system.school === "nec" && d.system.level <= 6);
let uu = [];
try { const wl = dnd5e.registry.spellLists.forType("class","wizard"); uu = wl ? [...(wl.uuids ?? [])] : []; out.wizListSize = uu.length; } catch(e) { out.regErr = String(e); }
out.necro = nec.map(d => ({ lvl: d.system.level, name: d.name, wizard: uu.length ? uu.includes(d.uuid) : null }))
  .sort((a,b)=>a.lvl-b.lvl||a.name.localeCompare(b.name));
const cl = game.packs.get("dnd-players-handbook.classes");
const cdocs = await cl.getDocuments();
out.wizSubclasses = cdocs.filter(d => d.type==="subclass" && d.system.classIdentifier==="wizard").map(d=>d.name);
return out;

const out = { world: game.world.id, lookup: !!game.pentaryn?.rules };
const sp = game.packs.get("dnd-players-handbook.spells");
const docs = await sp.getDocuments();
const nec = docs.filter(d => d.system.school === "nec" && d.system.level <= 6);
let uu = [];
try { const wl = dnd5e.registry.spellLists.forType("class","wizard"); uu = wl ? [...(wl.uuids ?? [])] : []; out.wizListSize = uu.length; } catch(e) { out.regErr = String(e); }
out.necro = nec.map(d => `${d.system.level} ${d.name}${uu.length ? (uu.includes(d.uuid) ? " [W]" : "") : ""}`)
  .sort();
const cl = game.packs.get("dnd-players-handbook.classes");
const cdocs = await cl.getDocuments();
out.wizSubclasses = cdocs.filter(d => d.type==="subclass" && d.system.classIdentifier==="wizard").map(d=>d.name);
return out;

const cfg = foundry.utils.duplicate(game.settings.get("core","moduleConfiguration"));
cfg["pentaryn-lookup"] = true;
await game.settings.set("core","moduleConfiguration", cfg);
setTimeout(() => foundry.utils.debouncedReload ? foundry.utils.debouncedReload() : location.reload(), 500);
return { set: true };

const r = game.pentaryn?.rules; if (!r) return { active: game.modules.get("pentaryn-lookup")?.active, rules: false };
const st = await r.selftest(); const s = await r.search("Magic Jar");
return { selftest: st?.ok ?? st, sample: s.slice?.(0,2) ?? s };

const mods=[...game.modules].filter(m=>m.active).map(m=>({id:m.id,title:m.title,v:m.version,type:m.type||'module'}));
const users=game.users.map(u=>({name:u.name,role:u.role,roleName:Object.keys(CONST.USER_ROLES).find(k=>CONST.USER_ROLES[k]===u.role),hasPw:!!u.password}));
return {world:game.world.id,mods,users,counts:{scenes:game.scenes.size,actors:game.actors.size,items:game.items.size,journals:game.journal.size}};

const ns={};for(const s of game.settings.storage.get('world')){const [n,...k]=s.key.split('.');(ns[n]??=[]).push(k.join('.'));}
const packs=game.packs.filter(p=>p.metadata.packageType!=='system'||false).map(p=>({id:p.collection,type:p.documentName,locked:p.locked,pkg:p.metadata.packageName,n:p.index.size}));
const sys=game.packs.filter(p=>p.metadata.packageType==='system'&&['Scene'].includes(p.documentName)).map(p=>p.collection);
return {ns,packs:packs.filter(p=>p.type==='Scene'||!p.locked),scenePacksAll:game.packs.filter(p=>p.documentName==='Scene').map(p=>({id:p.collection,locked:p.locked,n:p.index.size})),sys,
perms:game.settings.get('core','permissions')&&Object.keys(game.settings.get('core','permissions')).length,pto:game.settings.get('core','prototypeTokenOverrides')};

const out={world:game.world.id,folders:game.folders.filter(f=>f.type==="Actor").map(f=>f.name+"|"+f.id)};
const pick=a=>{const p=a.prototypeToken;return {name:a.name,id:a.id,folder:a.folder?.name,img:a.img,type:a.type,tex:p.texture.src,scale:p.texture.scaleX,w:p.width,h:p.height,ring:p.ring?.enabled,subj:p.ring?.subject?.texture,hidden:p.hidden,dn:p.displayName,disp:p.disposition,lock:p.lockRotation,actorLink:p.actorLink}};
out.markers=game.actors.filter(a=>/markers\/marker-/.test(a.prototypeToken.texture.src)||/^Marker/.test(a.name)).map(pick);
out.faded=game.actors.filter(a=>/faded/.test(a.prototypeToken.texture.src+a.img)).map(pick);
return out;

const c={};const add=(src,f)=>{for(const k of Object.keys(f||{})){(c[k]??={})[src]=(c[k][src]||0)+1}};
for(const s of game.scenes){add('scene',s.flags);s.tokens.forEach(t=>add('token',t.flags));s.walls.forEach(w=>add('wall',w.flags));s.tiles.forEach(t=>add('tile',t.flags));s.lights.forEach(t=>add('light',t.flags));s.drawings.forEach(t=>add('drawing',t.flags));s.regions?.forEach(t=>add('region',t.flags));}
game.actors.forEach(a=>{add('actor',a.flags);a.items.forEach(i=>add('actorItem',i.flags))});
game.journal.forEach(j=>add('journal',j.flags));game.macros.forEach(j=>add('macro',j.flags));
const gen=game.scenes.filter(s=>JSON.stringify(s.flags).match(/comfy|generat/i)).map(s=>s.name).slice(0,10);
const macros=game.macros.map(m=>m.name);
return {c,gen,macros,rollTables:game.tables.size,playlists:game.playlists.size,folders:game.folders.size};

const g=(n,k)=>{try{return game.settings.get(n,k)}catch(e){return 'ERR'}};
return {bridgeLast:g('foundry-mcp-bridge','lastConnectionState'),autoRecon:g('foundry-mcp-bridge','autoReconnectEnabled'),ties:{playerAccess:g('pentaryn-ties','playerAccess'),adv:g('pentaryn-ties','advantageStacking')},ech:{x:g('enhancedcombathud-dnd5e','explodeItemActivities'),w:g('enhancedcombathud-dnd5e','showWeaponsItems'),r:g('enhancedcombathud','rangepickerclear'),o:g('enhancedcombathud','openCombatStart')},
walls:{pw:game.modules.get('pentaryn-walls')?.active,api:Object.keys(game.pentaryn||{})},
seafootUnlocked:!game.packs.get('pentaryn-seafoot-maps.scenes').locked,
actorFolders:game.folders.filter(f=>f.type==='Actor').map(f=>f.name).slice(0,40),
tokenish:game.actors.filter(a=>/citizen|crowd|extra|commoner|gray|grey|1-9|\b\d\b/i.test(a.name)).map(a=>a.name).slice(0,30)};

const fm=n=>game.folders.find(f=>f.type==='Actor'&&f.name===n);
const mk=game.actors.filter(a=>a.name.startsWith('Marker')).map(a=>({n:a.name,img:a.img,tok:a.prototypeToken.texture.src,folder:a.folder?.name}));
const ex=game.actors.filter(a=>a.folder?.name==='Scene Extras').map(a=>({n:a.name,tok:a.prototypeToken.texture.src}));
return {mk,ex,landing:game.scenes.filter(s=>/splash|title|landing/i.test(s.name)).map(s=>({n:s.name,bg:s.background.src})),nav:game.scenes.filter(s=>s.navigation).length};

const active = game.modules.filter(m=>m.active).map(m=>m.id+"@"+m.version).sort();
return {world: game.world.id, title: game.world.title, bg: game.world.background, user: game.user.name, isGM: game.user.isGM,
users: game.users.map(u=>[u.name,u.role]), activeCount: active.length, active,
walls: game.modules.get("pentaryn-walls")?.active, wallsApi: !!game.pentaryn?.walls,
rules: game.settings.get("dnd5e","rulesVersion"), lockRot: game.settings.get("core","prototypeTokenOverrides")?.npc?.lockRotation ?? game.settings.get("core","prototypeTokenOverrides"),
ties: [game.settings.get("pentaryn-ties","playerAccess"), game.settings.get("pentaryn-ties","advantageStacking")],
argon: game.settings.get("enhancedcombathud-dnd5e","explodeItemActivities"),
seafootLocked: game.packs.get("pentaryn-seafoot-maps.scenes")?.locked,
scenePacks: game.packs.filter(p=>p.documentName==="Scene").map(p=>[p.collection,p.index.size])};

const p = game.packs.get("pentaryn-seafoot-maps.scenes");
await p.configure({locked:false});
const st = await game.pentaryn.rules.selftest();
return {seafootLocked: p.locked, selftest: st, apis: Object.keys(game.pentaryn||{}), macros: game.macros.map(m=>m.name), folders: game.folders.map(f=>[f.type,f.name]).length};

