args.script:
game.actors.reset?.();
const bad=[];const by={};
for(const a of game.actors){const f=a.folder?.name;by[f]=(by[f]||0)+1;const p=a.prototypeToken;
 for(const u of [a.img,p.texture.src,p.ring.subject.texture]){const r=await fetch("/"+u,{method:"HEAD"});if(!r.ok)bad.push([a.name,u,r.status]);}
 if(!p.lockRotation||p.ring.enabled)bad.push([a.name,"cfg"]);}
return {world:game.world.id,total:game.actors.size,by,bad};

const mods = [...game.modules].filter(m=>m.active).map(m=>`${m.id}@${m.version}`).sort();
const inactive = Object.entries(game.settings.get("core","moduleConfiguration")).filter(([k,v])=>!v).map(([k])=>k);
const users = game.users.map(u=>({name:u.name, role:u.role, hasPw:!!(u._source.password), hasSalt:!!(u._source.passwordSalt)}));
const pto = game.settings.get("core","prototypeTokenOverrides");
const pto2 = Object.fromEntries(Object.entries(pto).map(([k,v])=>[k,v?.lockRotation]));
const perms = game.settings.get("core","permissions");
const packs = game.packs.filter(p=>p.documentName==="Scene").map(p=>({id:p.collection, n:p.index.size, locked:p.locked}));
return {world:game.world.id, title:game.world.title, bg:game.world.background, desc:game.world.description, sys:game.system.id+"@"+game.system.version, core:game.version,
 rules: game.settings.get("dnd5e","rulesVersion"), modsActive: mods.length, mods, inactiveInConfig: inactive, users, lockRotation:pto2, permKeys:Object.keys(perms).length,
 packs, counts:{scenes:game.scenes.size, actors:game.actors.size, journals:game.journal.size, macros:game.macros.size, folders:game.folders.size},
 apis:{walls:!!game.pentaryn?.walls, ties:!!game.pentaryn?.ties, import:!!game.pentaryn?.import, rules:!!game.pentaryn?.rules, pings:!!game.pentaryn?.pings, dropbin:!!game.pentaryn?.dropbin},
 ech:{rangepickerclear:game.settings.get("enhancedcombathud","rangepickerclear"), openCombatStart:game.settings.get("enhancedcombathud","openCombatStart"), explode:game.settings.get("enhancedcombathud-dnd5e","explodeItemActivities"), showWeapons:game.settings.get("enhancedcombathud-dnd5e","showWeaponsItems")},
 ties:{playerAccess:game.settings.get("pentaryn-ties","playerAccess"), adv:game.settings.get("pentaryn-ties","advantageStacking")},
 bridgeAuto: game.settings.get("foundry-mcp-bridge","autoReconnectEnabled"),
 notifications: ui.notifications?.active?.length ?? ui.notifications?.queue?.length, chat: game.messages.size};

const folders = game.folders.filter(f=>f.type==="Actor").map(f=>({id:f.id,name:f.name,n:game.actors.filter(a=>a.folder?.id===f.id).length}));
const actors = game.actors.map(a=>{const t=a.prototypeToken; return {name:a.name, type:a.type, folder:a.folder?.name, img:a.img, src:t.texture.src, subj:t.ring.subject.texture, ring:t.ring.enabled, w:t.width,h:t.height, scale:t.texture.scaleX, disp:t.disposition, dn:t.displayName, lock:t.lockRotation, link:t.actorLink, hidden:t.hidden, items:a.items.size};});
const ip = {};
for (const k of ["currencies","itemFilters","systemFound","defaultItemPileActorID","populationTablesFolder"]) { try { ip[k] = game.settings.get("item-piles",k); } catch(e){ ip[k]="ERR "+e.message; } }
ip.currenciesLen = Array.isArray(ip.currencies)?ip.currencies.length:null; delete ip.currencies; ip.itemFiltersLen = Array.isArray(ip.itemFilters)?ip.itemFilters.length:null; delete ip.itemFilters;
let cc=null; try { cc = game.settings.get("core","compendiumConfiguration"); } catch(e){cc="ERR"}
return {folders, actors, macros: game.macros.map(m=>m.name), ip, compendiumConfigKeys: cc && typeof cc==="object" ? Object.keys(cc).length : cc, chat: game.messages.map(m=>m.flavor||m.content?.slice(0,60))};

const cc = game.settings.get("core","compendiumConfiguration");
const folderIds = new Set(game.folders.map(f=>f.id));
const entries = Object.entries(cc);
const dangling = entries.filter(([pack,cfg])=>cfg?.folder && !folderIds.has(cfg.folder)).map(([p,c])=>p+"->"+c.folder);
const unknownPacks = entries.filter(([pack])=>!game.packs.get(pack)).map(([p])=>p);
const compFolders = game.folders.filter(f=>f.type==="Compendium").map(f=>f.name);
const modIssues = [...game.modules].filter(m=>m.active).map(m=>({id:m.id, unavailable:m.unavailable, incompatible:m.incompatibleWithCoreVersion})).filter(m=>m.unavailable||m.incompatible);
return {ccEntries:entries.length, dangling, unknownPacks, compFolders, modIssues, worldFlags: game.world.flags, ownershipDefault: game.actors.contents[0]?.ownership?.default};

const before = game.settings.get('foundry-mcp-bridge','mapGenAutoStart');
await game.settings.set('foundry-mcp-bridge','mapGenAutoStart', false);
return {world: game.world.id, before, after: game.settings.get('foundry-mcp-bridge','mapGenAutoStart')};

const re = /under|cave|cavern|prison|cell|jail|dungeon|fung|mushroom|shroom|drow|spider|web|grotto|mine|deep|abyss|chasm|lava|tunnel|crypt|lair|duergar|myconid|gaol|oubliette|torture|ruin|subterr|sewer/i;
const out=[];
for (const p of game.packs.filter(p=>p.documentName==='Scene')) {
  const idx = await p.getIndex({fields:['walls','lights','thumb']});
  for (const e of idx) if (re.test(e.name)) out.push([p.collection, e._id, e.name, e.walls?.length ?? null, e.lights?.length ?? null]);
}
return {count: out.length, packs: game.packs.filter(p=>p.documentName==='Scene').map(p=>p.collection+':'+p.index.size), out};

const ids = {"dnd-dungeon-masters-guide.scenes":["dmgUnderdarkWarr","dmgDungeonHideou","dmgMine000000000"],"mad-endlesswiz.mad-endlesswiz-maps":["XdztM63pjc9nwNLO","s7kWp2zIzo5ihsU7"],"pentaryn-seafoot-maps.scenes":["1AgMbJuXGpgoD9wx","6Hs4FHhWYhgSK605","pfEPZgXH5MSaUL2W","EDJYGMiBk5d0deEg","HrKj6ZgWJGkM9g7j","UTc1KnXPxaa6dSDl","3L7PArmd7RTkC8vp","CNc2bxrUQISGX7HG","qKloNP8Sq4pdWGdZ","xl7y5aWzbO0CiURG","tbY9HU5nR4XcH3RQ","Bge65NKHLOmd9mlv","YJ3FMDmBrXNLkteP","iN78hdDn8RtZvgPP","kKC46FI10aWNwXJ5","fPiPwARdxvSJJEJ2","evG6XTNHUSH17Nb4","QHhh2i8Uy70qYTtz","FxjR6bs0bEpnxiwW","964442DqCkNcOMce","hHqZX1P58XrRP7bc","WwzXrirOwhPshZJf","SuxT2S3T7bEauCWs","fafvrXDntD5q5G1b","qQhs87QlMBkDQykC","Q9sK72fQCvgOrw5Q"]};
