for (const [pk,list] of Object.entries(ids)) { const p=game.packs.get(pk);
 const idx = await p.getIndex({fields:['thumb','background.src','environment.darknessLevel','environment.globalLight.enabled','width','height','grid.size','tokenVision','levels']});
 for (const id of list){ const e=idx.get(id); out.push({pk,id,name:e.name,thumb:e.thumb,bg:e.background?.src,dark:e.environment?.darknessLevel,global:e.environment?.globalLight?.enabled,vision:e.tokenVision,w:e.width,h:e.height,grid:e.grid?.size}); } }
return out;

const want={"dnd-dungeon-masters-guide.scenes":["dmgUnderdarkWarr","dmgDungeonHideou"],"pentaryn-seafoot-maps.scenes":["6Hs4FHhWYhgSK605","1AgMbJuXGpgoD9wx","pfEPZgXH5MSaUL2W","EDJYGMiBk5d0deEg","HrKj6ZgWJGkM9g7j","UTc1KnXPxaa6dSDl","xl7y5aWzbO0CiURG","tbY9HU5nR4XcH3RQ","YJ3FMDmBrXNLkteP","iN78hdDn8RtZvgPP","QHhh2i8Uy70qYTtz","fafvrXDntD5q5G1b","Bge65NKHLOmd9mlv"]};
const out=[];
for (const [pk,ids] of Object.entries(want)) for (const id of ids){ const d=await game.packs.get(pk).getDocument(id); const o=d.toObject();
 const s=JSON.stringify(o); const imgs=[...new Set((s.match(/"(?:src|img)":"([^"]+\.(?:webp|png|jpg|jpeg))"/g)||[]).map(x=>x.split('":"')[1].slice(0,-1)))].filter(x=>!/token|icons\//i.test(x)).slice(0,4);
 out.push({name:d.name,imgs,doors:o.walls.filter(w=>w.door>0).length,lights:o.lights.length,levels:o.levels?.length}); }
return out;

const p=game.packs.get('pentaryn-seafoot-maps.scenes');
const r={};
for (const id of ['pfEPZgXH5MSaUL2W','HrKj6ZgWJGkM9g7j']){const d=(await p.getDocument(id)).toObject();
const sum={}; for(const l of d.lights){const k=`${l.config.color}|dim${l.config.dim}|bright${l.config.bright}|${l.config.animation?.type}`; sum[k]=(sum[k]||0)+1;}
r[d.name]={sum, env:d.environment, folders: game.folders.filter(f=>f.type==='Scene').map(f=>f.name)};}
return r;

if (game.world.id!=='pentaryn') return 'wrong world '+game.world.id;
