const picks=[['HrKj6ZgWJGkM9g7j','Drow Prison (Devils Hold Prison)',true],['6Hs4FHhWYhgSK605','Underdark Caverns',true],['pfEPZgXH5MSaUL2W','Fungal Caverns (glowing shrooms)',false],['1AgMbJuXGpgoD9wx','Underdark Abyss',true],['QHhh2i8Uy70qYTtz','The Tangled Caverns (webs)',true],['tbY9HU5nR4XcH3RQ','Fallen Dungeon of Bron’Darha',true],['YJ3FMDmBrXNLkteP','Ruined Dwarven Vaults',true]];
const pack=game.packs.get('pentaryn-seafoot-maps.scenes'); const out=[], errs=[];
for (const [id,name,strip] of picks){
