  try { await s.update({'environment.darknessLevel':1,'environment.darknessLock':true,'environment.globalLight.enabled':false,tokenVision:true,'fog.exploration':true}); } catch(e){errs.push(name+' update: '+e.message)}
  const src=s._source;
  out.push({id:s.id,name:s.name,folder:s.folder?.name,walls:src.walls.length,doors:src.walls.filter(w=>w.door>0).length,lights:src.lights.length,dark:src.environment.darknessLevel,global:src.environment.globalLight.enabled});
}
return {out,errs,dupes:game.scenes.filter(s=>s.folder?.id===folder.id).length};

const kp=(await game.packs.get('pentaryn-seafoot-maps.scenes').getDocument('UTc1KnXPxaa6dSDl')).toObject();
const s=game.scenes.get('HrKj6ZgWJGkM9g7j');
