if (game.world.id !== 'pentaryn') return 'WRONG WORLD';
const A = game.pentaryn.ties.attributes;
const pc = game.actors.get('RNDTDBlFXxZ7Uc8i');
const plan = { witchesofelderholt: null, wardwitches: null, marrithshistory: null }; // null = all rows
const granted = foundry.utils.deepClone(pc.getFlag('pentaryn-ties','granted') ?? {});
const wrote = [];
for (const [attrId, labels] of Object.entries(plan)) {
  const entry = A.describe(attrId);
  for (const row of entry.lore) {
    if (labels && !labels.includes(row.label)) continue;
    granted[`attr:${attrId}:${row.id}`] = { text: row.text, when: Date.now(), icon: entry.icon, source: `${entry.title} — ${row.label}` };
    wrote.push(`${attrId}:${row.label}`);
  }
}
await pc.update({ 'flags.pentaryn-ties.granted': granted });
const keys = Object.keys(pc.getFlag('pentaryn-ties','granted'));
return { n: wrote.length, keys: keys.length, sample: pc.getFlag('pentaryn-ties','granted')[keys[0]], iconOf: A.describe('witchesofelderholt').icon };

