let t0 = Date.now();
for (const attrId of ['witchesofelderholt','wardwitches','marrithshistory']) for (const row of A.describe(attrId).lore) { const k = `attr:${attrId}:${row.id}`; if (granted[k]) granted[k].when = t0++; }
await pc.update({ 'flags.pentaryn-ties.granted': granted });
