const rows = A.of(pc, null, { viewer: pc }).map(r => r.id);
const per = Object.fromEntries(rows.map(id => [id, core.grantsForEntry(pc.getFlag('pentaryn-ties','granted'), '', { attributeIds: [id] }).map(g => g.source.split(' — ')[1])]));
const html = ui.buildAttributesHTML(pc, pc);
return { rows, per, htmlHasGrant: html.includes('Leave the witches alone'), htmlLen: html.length };

if (game.world.id !== 'pentaryn') return 'WRONG WORLD';
