const ids = ['witchesofelderholt','wardwitches','marrithshistory','lonepeak','thegroundstruck','taloshistory','stardruids','brenfen','fenwardensofbrenfen','cavenshistory'];
const pcs = ['RNDTDBlFXxZ7Uc8i','IxcfWOvpcKID6bdn','pfCQRWnqsQjkZQnB'].map(id => game.actors.get(id));
const bad = /quintus|emperor|empire|imperium|throne|destin|\border\b|legion|edict|censorate|dynast|crown|reign|haven/i;
const blob = JSON.stringify(A.list().filter(e => ids.includes(e.id))) + JSON.stringify(pcs.map(p => p.flags['pentaryn-ties']));
const hits = [...blob.matchAll(new RegExp(bad.source, 'gi'))].map(m => blob.slice(Math.max(0, m.index - 40), m.index + 30));
return {
  entries: A.list().filter(e => ids.includes(e.id)).map(e => [e.id, e.parent, e.dc, e.skill, e.whenKnown, e.whenCarried, e.secret, e.hold, e.lore.length, e.reviewedAt, e.source]),
  unreviewedIncludesAll: ids.every(id => A.unreviewed().some(e => (e.id ?? e) === id)),
  broken: pcs.map(p => [p.name, A.broken(p)]),
  pcs: pcs.map(p => { const f = p.flags['pentaryn-ties']; return [p.name, f.attributes, (f.lore ?? []).length, Object.keys(f.granted ?? {}).length, (f.known ?? []).map(k => k.name)]; }),
  knowledge: Object.fromEntries(pcs.map(p => [p.name, Object.keys(A.knows()[p.id] ?? {})])),
  secrecyHits: hits
};

