const run=(id, sq, refs=[])=>{const A=game.scenes.get(id);
const G=150,X0=A.dimensions.sceneX,Y0=A.dimensions.sceneY,COLS=Math.round(A.width/G),ROWS=Math.round(A.height/G);
const walls=A.walls.filter(w=>w.move>0 && !w.door).map(w=>w.c);
const ccw=(a,b,c)=>(c[1]-a[1])*(b[0]-a[0])>(b[1]-a[1])*(c[0]-a[0]);
const cross=(p1,p2,p3,p4)=>(ccw(p1,p3,p4)!==ccw(p2,p3,p4))&&(ccw(p1,p2,p3)!==ccw(p1,p2,p4));
const c=(i,j)=>[X0+i*G+G/2,Y0+j*G+G/2];
const bl=(a,b)=>walls.some(w=>cross(a,b,[w[0],w[1]],[w[2],w[3]]));
const lab=Array.from({length:COLS},()=>Array(ROWS).fill(-1));let n=0;const sizes=[];
for(let i=0;i<COLS;i++)for(let j=0;j<ROWS;j++){if(lab[i][j]>=0)continue;const q=[[i,j]];lab[i][j]=n;let k=0;
while(q.length){const[a,b]=q.pop();k++;for(const[da,db]of[[1,0],[-1,0],[0,1],[0,-1]]){const x=a+da,y=b+db;if(x<0||y<0||x>=COLS||y>=ROWS||lab[x][y]>=0)continue;if(bl(c(a,b),c(x,y)))continue;lab[x][y]=n;q.push([x,y]);}}sizes.push(k);n++;}
const L=(x,y)=>{const i=Math.floor((x-X0)/G),j=Math.floor((y-Y0)/G);return [i,j,lab[i][j],sizes[lab[i][j]]];};
return {sq:L(...sq), refs:refs.map(r=>L(...r))};};
