out.size = await grab("Movement and Position", /Creature Size/, 900);
out.reachProp = await grab("Weapon Properties", /Reach\b/, 300);
out.melee = await grab("Melee Attacks", /reach/i, 400);
out.los = await grab("Miniatures", /Line of Sight/, 700);
const s = await R.search("encounter distance"); out.encDist = (s.hits??s).slice(0,4).map(x=>[x.book,x.journal,x.page,x.snippet]);
const s2 = await R.search("Targets in Area of Effect"); out.aoe = (s2.hits??s2).slice(0,2).map(x=>[x.book,x.page,x.snippet]);
const s3 = await R.search("Range 120 feet"); out.r120 = (s3.hits??s3).length;
const s4 = await R.search("Heavily Obscured"); out.obsc = (s4.hits??s4).slice(0,1).map(x=>[x.book,x.page,x.snippet]);
return out;

