const idx = await p.getIndex({fields:["system.range","system.level"]});
const c = {}; for (const e of idx) { const r = e.system?.range; const k = r?.value ? `${r.value} ${r.units}` : (r?.units ?? "?"); c[k]=(c[k]??0)+1; }
const eq = game.packs.get("dnd-players-handbook.equipment");
const ei = await eq.getIndex({fields:["type","system.range","system.properties","system.type"]});
const w = ei.filter(e=>e.type==="weapon" && e.system?.range?.value).map(e=>`${e.name} ${e.system.range.value}/${e.system.range.long}`);
const t = await game.pentaryn.rules.page("Travel Pace"); const tt = t.text ?? ""; const i = tt.search(/Travel Terrain Terrain/);
return { spellRanges: Object.entries(c).sort((a,b)=>b[1]-a[1]).slice(0,20), weapons: w, terrain: tt.slice(i, i+900) };

