out.markerFolder = mf?.id; out.markers = mf?.contents.map(a=>({id:a.id,name:a.name,type:a.type,size:a.system.traits?.size,w:a.prototypeToken.width,lock:a.prototypeToken.flags?.dnd5e?.lockSize,hidden:a.prototypeToken.hidden, own:a.ownership.default}));
