out.wallHeightScenes=[...new Set(wh)];
return out;

const s = game.scenes.get("gwuR3bitZ3lrpWJZ");
const lvl = s.firstLevel ?? s.levels.contents[0];
const toks = s.tokens.contents;
const t0 = performance.now();
const C = CONFIG.Canvas.polygonBackends.sight;
const centre = t => t.getCenterPoint ? t.getCenterPoint() : {x:t.x+t.width*s.grid.size/2,y:t.y+t.height*s.grid.size/2};
let pairs=0, blocked=0; const sample=[];
for (let i=0;i<toks.length;i++) for (let j=i+1;j<toks.length;j++) {
  const a=centre(toks[i]), b=centre(toks[j]);
  const hit = C.testCollision({x:a.x,y:a.y,elevation:toks[i].elevation}, {x:b.x,y:b.y,elevation:toks[j].elevation}, {type:"sight", mode:"any", level:lvl, useThreshold:true, edgeTypes:{source:false}});
  pairs++; if (hit) blocked++;
  if (sample.length<4) { const d = s.grid.measurePath([a,b]).distance; sample.push({a:toks[i].name,b:toks[j].name,hit,ft:Math.round(d*10)/10}); }
}
const ms = performance.now()-t0;
const offs = toks[0].getOccupiedGridSpaceOffsets();
