return {initEdgesAfter:s.initializedEdges, lvl:lvl?.id, edges: lvl.edges.size, pairs, blocked, ms:Math.round(ms), sample, offs0: offs, tok0:[toks[0].name,toks[0].x,toks[0].y,toks[0].width,toks[0].level], dims:{w:s.dimensions.width,h:s.dimensions.height,sceneRect:s.dimensions.sceneRect, dp:s.dimensions.distancePixels}, folders, markerActors, gridClass: s.grid.constructor.name, diagonals: s.grid.diagonals};

