const props = game.folders.find(f=>f.type==="Actor"&&f.name==="Scene Props")?.contents.map(a=>[a.id,a.name,a.type,a.prototypeToken.width,a.prototypeToken.flags?.dnd5e?.lockSize]);
let placed=[]; for (const s of game.scenes) for (const t of s.tokens) if (f.contents.some(a=>a.id===t.actorId)) placed.push([s.name,t.name,t.id]);
const flagged=[]; for (const s of game.scenes) for (const t of s.tokens) if (t.flags?.["pentaryn-prompt"]||t.flags?.pentaryn) flagged.push([s.name,t.name]);
return {m:m.slice(0,2), count:m.length, props, placed, flagged, activeGM: game.users.activeGM?.name};

const s = game.scenes.get("gwuR3bitZ3lrpWJZ"); const g=s.grid.size; const d=s.dimensions;
const lvl = s.levels.contents[0]; const bgSrc = lvl.background.src;
const t0=performance.now();
const load = src => new Promise((res,rej)=>{const i=new Image(); i.crossOrigin="anonymous"; i.onload=()=>res(i); i.onerror=()=>rej(new Error("load "+src)); i.src=foundry.utils.getRoute(src.startsWith("/")?src:"/"+src);});
const bg = await load(bgSrc); const t1=performance.now();
const tok = s.tokens.contents[0]; const cx=tok.x+tok.width*g/2, cy=tok.y+tok.height*g/2;
const R = 6*g; // 30 ft margin -> 12x12 squares
const crop = {x:cx-R, y:cy-R, w:2*R, h:2*R};
const OUT=768; const c=new OffscreenCanvas(OUT,OUT); const ctx=c.getContext("2d"); const k=OUT/crop.w;
ctx.drawImage(bg, crop.x-d.sceneX, crop.y-d.sceneY, crop.w, crop.h, 0,0,OUT,OUT);
let drawn=0;
for (const t of s.tokens) { const r={x:t.x,y:t.y,w:t.width*g,h:t.height*g}; if (r.x+r.w<crop.x||r.x>crop.x+crop.w||r.y+r.h<crop.y||r.y>crop.y+crop.h) continue;
  const src = t.ring?.enabled && t.ring.subject?.texture ? t.ring.subject.texture : t.texture.src; try { const im=await load(src); ctx.drawImage(im,(r.x-crop.x)*k,(r.y-crop.y)*k,r.w*k,r.h*k); drawn++; } catch(e){}
  ctx.strokeStyle="#ff0"; ctx.lineWidth=2; ctx.strokeRect((r.x-crop.x)*k,(r.y-crop.y)*k,r.w*k,r.h*k); ctx.fillStyle="#fff"; ctx.font="14px sans-serif"; ctx.fillText(t.name.slice(0,18),(r.x-crop.x)*k,(r.y-crop.y)*k-2); }
ctx.strokeStyle="rgba(255,0,0,.8)"; ctx.lineWidth=2; for (const w of s.walls) { const [x0,y0,x1,y1]=w.c; ctx.beginPath(); ctx.moveTo((x0-crop.x)*k,(y0-crop.y)*k); ctx.lineTo((x1-crop.x)*k,(y1-crop.y)*k); ctx.stroke(); }
const blob = await c.convertToBlob({type:"image/webp", quality:0.8}); const png = await c.convertToBlob({type:"image/png"});
return {bgSrc, bgSize:[bg.naturalWidth,bg.naturalHeight], loadMs:Math.round(t1-t0), totalMs:Math.round(performance.now()-t0), drawn, webpKB:Math.round(blob.size/1024), pngKB:Math.round(png.size/1024), estTokens: Math.round(OUT*OUT/750)};

const s = game.scenes.get("iBdyqCrrPLU3DHMe"); const t = s.tokens.contents[0];
const pts = t.getVisibilityTestPoints(); const o = t.getMovementOrigin();
const bio = t.actor?.system?.details?.biography?.value ?? "";
return {name:t.name, n:pts.length, pts:pts.slice(0,3), origin:o, centre:t.getCenterPoint(), prev: foundry.applications.ux.TextEditor.implementation.previewHTML(bio, 120), ctype: t.actor?.system?.details?.type?.value, size: t.actor?.system?.traits?.size, flags:Object.keys(t.flags)};

