const out = markers.map(a => ({name: a.name, folder: a.folder?.name, w: a.prototypeToken.width, lock: a.prototypeToken.flags?.dnd5e?.lockSize ?? null, hiddenField: "hidden" in a.prototypeToken._source}));
return {world: game.world.id, count: out.length, folders: [...new Set(out.map(o=>o.folder))], sample: out.slice(0, 14), queries: Object.keys(CONFIG.queries).filter(k => k.startsWith("pentaryn-prompts") || k.includes("fork")), apiPrompts: !!game.pentaryn?.prompts};

