const level = scene.levels.get(a.level) ?? scene.firstLevel;
const t0 = performance.now();
try {
  out.hit = CONFIG.Canvas.polygonBackends.sight.testCollision(a.getMovementOrigin(), b.getMovementOrigin(), {type:"sight", mode:"any", level, useThreshold:true, edgeTypes:{source:false}});
} catch (e) { out.hitErr = String(e); }
