const scenes = [...game.scenes].map(s => ({ s, w: s.walls.size, t: s.tokens.size })).sort((a, b) => b.w - a.w);
const top = scenes.slice(0, 3).map(x => ({ name: x.s.name, walls: x.w, tokens: x.t, viewed: x.s.isView, levels: x.s.levels?.size }));
const { s: scene } = scenes[0];
const backend = CONFIG.Canvas.polygonBackends.sight;
const level = scene.firstLevel;
const toks = scene.tokens.contents.slice(0, 40);
const geo = toks.map(t => ({ o: t.getMovementOrigin(), pts: t.getVisibilityTestPoints() }));
const ptsCounts = geo.map(g => g.pts.length);
let calls = 0, pairs = 0, blocked = 0;
const t0 = performance.now();
outer: for (let a = 0; a < geo.length; a++) for (let b = 0; b < geo.length; b++) {
  if (a === b) continue;
  pairs++;
  let vis = false;
  for (const p of geo[b].pts) {
    calls++;
    const hit = backend.testCollision(geo[a].o, { x: p.x, y: p.y, elevation: p.elevation }, { type: "sight", mode: "any", level, useThreshold: true, edgeTypes: { source: false } });
    if (!hit) { vis = true; break; }
  }
  if (!vis) blocked++;
  if (performance.now() - t0 > 5000) break outer;
}
const ms = performance.now() - t0;
return { top, used: scene.name, ptsCounts: [...new Set(ptsCounts)], pairs, calls, blocked, ms: Math.round(ms), perCallUs: Math.round(ms / calls * 1000), perPairMs: +(ms / pairs).toFixed(3) };

const scene = game.scenes.getName("Fungal Caverns (glowing shrooms)");
const d = scene.dimensions, g = d.size;
const backend = CONFIG.Canvas.polygonBackends.sight;
const level = scene.firstLevel;
let seed = 7; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
const cols = Math.floor(d.sceneWidth / g), rows = Math.floor(d.sceneHeight / g);
const N = 40;
const items = [];
