const tick = () => new Promise(r => { const c = new MessageChannel(); c.port1.onmessage = () => { c.port1.close(); r(); }; c.port2.postMessage(0); });
const sleep = async ms => { const t0 = performance.now(); while (performance.now() - t0 < ms) await tick(); };
const t0 = performance.now(); await sleep(400); const a = performance.now() - t0;
const t1 = performance.now(); await new Promise(r => setTimeout(r, 10)); const b = performance.now() - t1;
return { sleep400: Math.round(a), setTimeout10: Math.round(b), hidden: document.hidden };

